 "openapi": "3.0.3",
 "info": {
  "title": "Freya Bank voice statement services",
  "version": "2026-10-01",
  "description": "Seven POST services, JSON in/out, UTF-8. Request {data, call}; answer {data, result}. Dates dd.MM.yyyy, amounts JSON numbers. Get a bearer token first (client-credentials at tokenUrl; the test environment does not check it, send it anyway). Service names contain dots."
 },
 "servers": [
  {
   "url": "https://bank-mock.tccbank2026-yc.workers.dev/freyabank/voice/v1"
  }
 ],
 "components": {
  "securitySchemes": {
   "bankOAuth": {
    "type": "oauth2",
    "flows": {
     "clientCredentials": {
      "tokenUrl": "https://bank-mock.tccbank2026-yc.workers.dev/freyabank/oauth2/token",
      "scopes": {
       "voice.statement": "statement services"
      }
     }
    }
   }
  }
 },
